import sys


def parse_tile(t):
    return int(t[0]), t[1]


def is_mentsu(tiles):
    nums = [x[0] for x in tiles]
    suits = [x[1] for x in tiles]

    # Koutsu
    if nums[0] == nums[1] == nums[2] and suits[0] == suits[1] == suits[2]:
        return True

    # Shuntsu
    if suits[0] == suits[1] == suits[2]:
        nums.sort()
        if nums[0] + 1 == nums[1] and nums[1] + 1 == nums[2]:
            return True

    return False


def need_one(a, b):
    na, sa = a
    nb, sb = b

    # Can complete a triplet with one tile
    if na == nb and sa == sb:
        return True

    # Can complete a sequence with one tile
    if sa == sb:
        d = abs(na - nb)
        if d == 1 or d == 2:
            return True

    return False


def main():
    tiles_str = sys.stdin.read().strip().split()
    tiles = [parse_tile(t) for t in tiles_str]

    if is_mentsu(tiles):
        print(0)
        return

    for i in range(3):
        for j in range(i + 1, 3):
            if need_one(tiles[i], tiles[j]):
                print(1)
                return

    print(2)


if __name__ == '__main__':
    main()

