import sys


def right_score(a, b, c):
    la = math.log(a)
    if abs(la) < 1e-15:
        return 0.0  # value == 1
    if la > 0:
        # maximize ln((b^c) * ln(a))
        return c * math.log(b) + math.log(la)
    else:
        # maximize negative number la * (b^c) => minimize b^c
        # compare by negative of ln(b^c)
        return -(c * math.log(b))


def left_score(a, b, c):
    la = math.log(a)
    if abs(la) < 1e-15:
        return 0.0  # value == 1
    if la > 0:
        # maximize ln((b*c) * ln(a))
        return math.log(b) + math.log(c) + math.log(la)
    else:
        # maximize negative number la * (b*c) => minimize b*c
        # compare by negative of ln(b*c)
        return -(math.log(b) + math.log(c))


