        tmp = 'tmp'
        while tmp in used or len(tmp) > 6:
            tmp += 'a'
        if len(tmp) > 6:
            # fallback guaranteed possible within constraints using letters/digits up to length 6
            for c1 in 'abcdefghijklmnopqrstuvwxyz':
                if c1 not in used:
                    tmp = c1
                    break
            else:
                found = False
                chars = 'abcdefghijklmnopqrstuvwxyz0123456789'
                for c1 in chars:
                    for c2 in chars:
                        cand = c1 + c2
                        if cand not in used:
                            tmp = cand
                            found = True
                            break
                    if found:
                        break

        # choose a file whose target class currently has no free names because of cycle
        if wrong_ex:
            src = next(iter(wrong_ex))
            src_type = 1
        else:
            src = next(iter(wrong_reg))
            src_type = 0
        do_move(src, tmp)

        # its old numeric name may become free in the opposite pool if it was occupying one
        v = parse_num(src)
        if v is not None:
            if 1 <= v <= e:
                free_ex.append(str(v))
            elif e + 1 <= v <= n:
                free_reg.append(str(v))

        # continue resolving all wrong files except tmp-holder now stored under tmp
        while free_ex or free_reg:
            progressed = False
            while free_ex and wrong_ex:
                s = next(iter(wrong_ex))
                d = free_ex.popleft()
                do_move(s, d)
                progressed = True
            while free_reg and wrong_reg:
                s = next(iter(wrong_reg))
                d = free_reg.popleft()
                do_move(s, d)
                progressed = True
            if not progressed:
                break

        # move tmp to final appropriate free slot
        if src_type == 1:
            dst = free_ex.popleft()
        else:
            dst = free_reg.popleft()
        ops.append((tmp, dst))

    print(len(ops))
    for a, b in ops:
        print('move', a, b)


if __name__ == '__main__':
    solve()

