import math


def egcd(a, b):
    if b == 0:
        return (a, 1, 0)
    g, x1, y1 = egcd(b, a % b)
    return (g, y1, x1 - (a // b) * y1)


def crt_two(r1, m1, r2, m2):
    # Solve x ≡ r1 (mod m1), x ≡ r2 (mod m2)
    g = math.gcd(m1, m2)
    diff = r2 - r1
    if diff % g != 0:
        return None, None

    m1g = m1 // g
    m2g = m2 // g
    lcm = m1 * m2g

    # Need t such that m1 * t ≡ diff (mod m2)
    # Divide by g: m1g * t ≡ diff/g (mod m2g)
    _, inv, _ = egcd(m1g, m2g)
    inv %= m2g
    t = ((diff // g) * inv) % m2g
    x0 = (r1 + m1 * t) % lcm
    return x0, lcm


def first_at_least(x0, step, low):
    if x0 >= low:
        return x0
    k = (low - x0 + step - 1) // step
    return x0 + k * step


