import sys


def can_measure(w, m):
    while m > 0:
        r = m % w
        if r == 0:
            m //= w
        elif r == 1:
            m = (m - 1) // w
        elif r == w - 1:
            m = (m + 1) // w
        else:
            return False
    return True


