def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    arr = list(map(int, data[1:1 + n]))
    start = tuple(sorted(arr))

    @lru_cache(maxsize=None)
    def win(state):
        # state is a sorted tuple
        if all(x == 0 for x in state):
            return False

        m = len(state)

        # Move 1: decrease one pile by x, 1 <= x <= ai
        for i in range(m):
            ai = state[i]
            for x in range(1, ai + 1):
                nxt = list(state)
                nxt[i] -= x
                nxt.sort()
                if not win(tuple(nxt)):
                    return True

        # Move 2: decrease all piles by x, 1 <= x <= min(state)
        mn = state[0]
        for x in range(1, mn + 1):
            nxt = tuple(v - x for v in state)
            # still sorted after subtracting same x from all
            if not win(nxt):
                return True

        return False

    print("BitLGM" if win(start) else "BitAryo")


