import sys


def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n, k = map(int, data)

    # Feasibility:
    # total ones = (# diagonal ones) + 2 * (# off-diagonal pairs)
    # so we need k = d + 2p with 0 <= d <= n.
    # This is possible iff k <= n^2 and parity of d can match k.
    # Since d can be any value from 0..n, this fails only when n is even and k is odd.
    if k > n * n or (n % 2 == 0 and k % 2 == 1):
        print(-1)
        return

    a = [[0] * n for _ in range(n)]

    # Greedy for lexicographically maximal matrix:
    # process row-major, deciding only upper triangle entries.
    # At diagonal (i,i), placing 1 costs 1 and makes the earliest possible cell maximal.
    # At off-diagonal (i,j), placing 1 forces (j,i)=1 too, cost 2.
    for i in range(n):
        for j in range(i, n):
            if i == j:
                if k >= 1:
                    a[i][j] = 1
                    k -= 1
            else:
                if k >= 2:
                    a[i][j] = 1
                    a[j][i] = 1
                    k -= 2

    if k != 0:
        print(-1)
        return

    out = []
    for row in a:
        out.append(' '.join(map(str, row)))
    sys.stdout.write('\n'.join(out))


if __name__ == '__main__':
    solve()

