    files = []  # (name, typ)
    used = set()
    e = 0
    for _ in range(n):
        name, t = input().split()
        t = int(t)
        files.append((name, t))
        used.add(name)
        if t == 1:
            e += 1

    def parse_num(s):
        if not s.isdigit():
            return None
        v = int(s)
        if 1 <= v <= n and str(v) == s:
            return v
        return None

    # correct occupied names
    correct_example_names = set()
    correct_regular_names = set()

    wrong_ex = set()   # names of example files currently wrong
    wrong_reg = set()  # names of regular files currently wrong

    type_of = {}
    for name, t in files:
