import sys
from collections import Counter


def solve() -> None:
    a = sys.stdin.readline().strip()
    b = sys.stdin.readline().strip()

    # If a has fewer digits, any permutation of a is <= b.
    if len(a) < len(b):
        print(''.join(sorted(a, reverse=True)))
        return

    counts = [0] * 10
    for ch in a:
        counts[ord(ch) - ord('0')] += 1

    n = len(a)
    bdigits = [ord(ch) - ord('0') for ch in b]
    ans = []

    def descending_rest() -> str:
        parts = []
        for d in range(9, -1, -1):
            if counts[d]:
                parts.append(str(d) * counts[d])
        return ''.join(parts)

    def dfs(pos: int, tight: bool) -> bool:
        if pos == n:
            return True

        limit = bdigits[pos] if tight else 9
        start = limit
        for d in range(start, -1, -1):
            if counts[d] == 0:
                continue
            if pos == 0 and d == 0:
                continue
            if tight and d > limit:
                continue

            counts[d] -= 1
            ans.append(str(d))

            if tight and d == limit:
                if dfs(pos + 1, True):
                    return True
            else:
                ans.append(descending_rest())
                return True

            ans.pop()
            counts[d] += 1

        return False

    dfs(0, True)
    print(''.join(ans))


