    p = 3
    while p * p <= n:
        if n % p == 0:
            c = 0
            while n % p == 0:
                n //= p
                c += 1
            fac[p] = c
        p += 2
    if n > 1:
        fac[n] = fac.get(n, 0) + 1
    return fac


def gen_divisors_from_factorization(items, idx=0, cur=1, out=None):
    if out is None:
        out = []
    if idx == len(items):
        out.append(cur)
        return out
    p, e = items[idx]
    val = 1
    for _ in range(e + 1):
        gen_divisors_from_factorization(items, idx + 1, cur * val, out)
        val *= p
    return out


def phi_from_m_factorization(n: int, m_primes):
    res = n
    t = n
    for p in m_primes:
        if t % p == 0:
