import sys


def digit_sum_str(s: str) -> int:
    return sum(ord(c) - 48 for c in s)


def main():
    x = sys.stdin.readline().strip()

    best = x
    best_sum = digit_sum_str(x)

    n = len(x)
    for i, ch in enumerate(x):
        if ch == '0':
            continue
        # Decrease this digit by 1 and fill the rest with 9s
        prefix = x[:i]
        mid = str(ord(ch) - 48 - 1)
        cand = prefix + mid + '9' * (n - i - 1)
        # Remove leading zeros, but keep at least one digit
        cand = cand.lstrip('0') or '0'
        if cand == '0':
            continue  # only positive integers are allowed

        s = digit_sum_str(cand)
        if s > best_sum or (s == best_sum and int(cand) > int(best)):
            best = cand
            best_sum = s

    print(best)


if __name__ == '__main__':
    main()

