    nb, sb = b

    # Can complete a triplet with one tile
    if na == nb and sa == sb:
        return True

    # Can complete a sequence with one tile
    if sa == sb:
        d = abs(na - nb)
        if d == 1 or d == 2:
            return True

    return False


