import sys


def solve() -> None:
    input = sys.stdin.readline
    n = int(input().strip())
    s = input().strip()

    total_g = s.count('G')
    if total_g == 0:
        print(0)
        return

    runs = []  # list of (char, length)
    i = 0
    while i < n:
        j = i
        while j < n and s[j] == s[i]:
            j += 1
        runs.append((s[i], j - i))
        i = j

    ans = 0

    # Extend a single G-run by one if there is another G elsewhere
    for ch, length in runs:
        if ch == 'G':
            if length < total_g:
                ans = max(ans, length + 1)
            else:
                ans = max(ans, length)

    # Merge two G-runs separated by exactly one S
    for k in range(1, len(runs) - 1):
        if runs[k][0] == 'S' and runs[k][1] == 1 and runs[k - 1][0] == 'G' and runs[k + 1][0] == 'G':
            left = runs[k - 1][1]
            right = runs[k + 1][1]
            merged = left + right
            if merged < total_g:
                merged += 1
            ans = max(ans, merged)

    print(ans)


if __name__ == "__main__":
    solve()

