    e = 0
    for _ in range(n):
        name, t = input().split()
        t = int(t)
        files.append((name, t))
        used.add(name)
        if t == 1:
            e += 1

    def parse_num(s):
        if not s.isdigit():
            return None
        v = int(s)
        if 1 <= v <= n and str(v) == s:
            return v
        return None

    # correct occupied names
    correct_example_names = set()
    correct_regular_names = set()

    wrong_ex = set()   # names of example files currently wrong
    wrong_reg = set()  # names of regular files currently wrong

    type_of = {}
    for name, t in files:
        type_of[name] = t
        v = parse_num(name)
        if t == 1:
            if v is not None and 1 <= v <= e:
                correct_example_names.add(v)
            else:
                wrong_ex.add(name)
        else:
            if v is not None and e + 1 <= v <= n:
                correct_regular_names.add(v)
            else:
                wrong_reg.add(name)

    free_ex = deque(str(i) for i in range(1, e + 1) if i not in correct_example_names)
    free_reg = deque(str(i) for i in range(e + 1, n + 1) if i not in correct_regular_names)

    ops = []

    def do_move(src, dst):
        ops.append((src, dst))
        used.discard(src)
        used.add(dst)
        t = type_of.pop(src)
        type_of[dst] = t
        if src in wrong_ex:
            wrong_ex.remove(src)
        if src in wrong_reg:
            wrong_reg.remove(src)

    # direct greedy moves while there are free proper names
    while free_ex or free_reg:
        progressed = False
        while free_ex and wrong_ex:
            src = next(iter(wrong_ex))
            dst = free_ex.popleft()
            do_move(src, dst)
            progressed = True
        while free_reg and wrong_reg:
            src = next(iter(wrong_reg))
            dst = free_reg.popleft()
            do_move(src, dst)
            progressed = True
        if not progressed:
            break

    if wrong_ex or wrong_reg:
        # Need temporary name to break cycles
        tmp = 'tmp'
        while tmp in used or len(tmp) > 6:
            tmp += 'a'
        if len(tmp) > 6:
            # fallback guaranteed possible within constraints using letters/digits up to length 6
            for c1 in 'abcdefghijklmnopqrstuvwxyz':
                if c1 not in used:
                    tmp = c1
                    break
            else:
                found = False
                chars = 'abcdefghijklmnopqrstuvwxyz0123456789'
                for c1 in chars:
                    for c2 in chars:
                        cand = c1 + c2
                        if cand not in used:
                            tmp = cand
                            found = True
                            break
                    if found:
                        break

        # choose a file whose target class currently has no free names because of cycle
        if wrong_ex:
            src = next(iter(wrong_ex))
            src_type = 1
        else:
            src = next(iter(wrong_reg))
            src_type = 0
        do_move(src, tmp)

        # its old numeric name may become free in the opposite pool if it was occupying one
        v = parse_num(src)
        if v is not None:
            if 1 <= v <= e:
                free_ex.append(str(v))
            elif e + 1 <= v <= n:
                free_reg.append(str(v))

        # continue resolving all wrong files except tmp-holder now stored under tmp
        while free_ex or free_reg:
            progressed = False
            while free_ex and wrong_ex:
                s = next(iter(wrong_ex))
                d = free_ex.popleft()
                do_move(s, d)
                progressed = True
            while free_reg and wrong_reg:
                s = next(iter(wrong_reg))
                d = free_reg.popleft()
                do_move(s, d)
                progressed = True
            if not progressed:
                break

        # move tmp to final appropriate free slot
        if src_type == 1:
            dst = free_ex.popleft()
        else:
            dst = free_reg.popleft()
        ops.append((tmp, dst))

    print(len(ops))
    for a, b in ops:
        print('move', a, b)


if __name__ == '__main__':
    solve()

