        q = val // m  # q = 2^(k+1)
        if q < 2 or not is_power_of_two(q):
            continue
        t = m * (q // 2)
        # Safety check
        mm = t
        while mm % 2 == 0:
            mm //= 2
        games = (t - mm) + (0 if mm == 1 else mm * (mm - 1) // 2)
        if games == n:
            ans.append(t)

    ans = sorted(set(ans))
    if not ans:
        print(-1)
    else:
        print('\n'.join(map(str, ans)))


