def mat_mul(A, B):
    n = len(A)
    C = [[0] * n for _ in range(n)]
    for i in range(n):
        Ai = A[i]
        Ci = C[i]
        for k in range(n):
            if Ai[k] == 0:
                continue
            a = Ai[k]
            Bk = B[k]
            for j in range(n):
                if Bk[j]:
                    Ci[j] += a * Bk[j]
    return C


def mat_pow(A, e):
    n = len(A)
    R = [[0] * n for _ in range(n)]
    for i in range(n):
        R[i][i] = 1
    while e > 0:
        if e & 1:
            R = mat_mul(R, A)
        A = mat_mul(A, A)
        e >>= 1
    return R


def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    s = data[1].strip()
    m = len(s)

    if m == 1:
        # Avoiding s means all characters are the opposite bit.
        print((1 << n) - 1)
        return

    L = m - 1
    N = 1 << L
    pat = int(s, 2)
    maskL = N - 1

    A = [[0] * N for _ in range(N)]
    for x in range(N):
        for b in (0, 1):
            w = (x << 1) | b  # length-m window as bits
            if w == pat:
