import sys
import math


def is_power_of_two(x: int) -> bool:
    return x > 0 and (x & (x - 1)) == 0


def main():
    data = sys.stdin.readline().strip()
    n = int(data)

    ans = []

    # Since final odd part m must satisfy m(m-1)/2 <= n
    # it is enough to check odd m up to this bound.
    limit = (1 + math.isqrt(1 + 8 * n)) // 2 + 2

    for m in range(1, limit + 1, 2):
        val = 2 * n - m * m + 3 * m
        if val <= 0:
            continue
        if val % m != 0:
            continue
        q = val // m  # q = 2^(k+1)
        if q < 2 or not is_power_of_two(q):
            continue
        t = m * (q // 2)
        # Safety check
        mm = t
        while mm % 2 == 0:
            mm //= 2
        games = (t - mm) + (0 if mm == 1 else mm * (mm - 1) // 2)
        if games == n:
            ans.append(t)

    ans = sorted(set(ans))
    if not ans:
        print(-1)
    else:
        print('\n'.join(map(str, ans)))


if __name__ == '__main__':
    main()

