        x = pieces[i]
        seen = set()
        for j in range(k):
            if caps[j] >= x and caps[j] not in seen:
                seen.add(caps[j])
                caps[j] -= x
                if dfs(i + 1):
                    return True
                caps[j] += x
        return False

    return dfs(0)


