import sys


def neighbors(state: str):
    adj = {
        0: [1, 2],
        1: [0, 3],
        2: [0, 3],
        3: [1, 2],
    }
    x = state.index('X')
    res = []
    s = list(state)
    for y in adj[x]:
        t = s[:]
        t[x], t[y] = t[y], t[x]
        res.append(''.join(t))
    return res


def reachable(start: str):
    q = deque([start])
    seen = {start}
    while q:
        cur = q.popleft()
        for nxt in neighbors(cur):
            if nxt not in seen:
                seen.add(nxt)
                q.append(nxt)
    return seen


def main():
    data = [line.strip() for line in sys.stdin if line.strip()]
    b = data[0] + data[1]
    e = data[2] + data[3]
    print("YES" if e in reachable(b) else "NO")


