    la = math.log(a)
    if abs(la) < 1e-15:
        return 0.0  # value == 1
    if la > 0:
        # maximize ln((b^c) * ln(a))
        return c * math.log(b) + math.log(la)
    else:
        # maximize negative number la * (b^c) => minimize b^c
        # compare by negative of ln(b^c)
        return -(c * math.log(b))


def left_score(a, b, c):
    la = math.log(a)
    if abs(la) < 1e-15:
        return 0.0  # value == 1
    if la > 0:
        # maximize ln((b*c) * ln(a))
        return math.log(b) + math.log(c) + math.log(la)
    else:
        # maximize negative number la * (b*c) => minimize b*c
        # compare by negative of ln(b*c)
        return -(math.log(b) + math.log(c))


def main():
    data = sys.stdin.read().strip().split()
    x, y, z = map(float, data)

    candidates = [
        (right_score(x, y, z), 'x^y^z'),
        (right_score(x, z, y), 'x^z^y'),
        (left_score(x, y, z), '(x^y)^z'),
        (left_score(x, z, y), '(x^z)^y'),
        (right_score(y, x, z), 'y^x^z'),
        (right_score(y, z, x), 'y^z^x'),
        (left_score(y, x, z), '(y^x)^z'),
        (left_score(y, z, x), '(y^z)^x'),
        (right_score(z, x, y), 'z^x^y'),
        (right_score(z, y, x), 'z^y^x'),
        (left_score(z, x, y), '(z^x)^y'),
        (left_score(z, y, x), '(z^y)^x'),
    ]

    best_score, best_expr = candidates[0]
    for score, expr in candidates[1:]:
        if score > best_score:
            best_score, best_expr = score, expr

    print(best_expr)


