import sys
from math import isqrt, gcd


def factorize(n: int):
    fac = {}
    c = 0
    while n % 2 == 0:
        n //= 2
        c += 1
    if c:
        fac[2] = c
    p = 3
    while p * p <= n:
        if n % p == 0:
            c = 0
            while n % p == 0:
                n //= p
                c += 1
            fac[p] = c
        p += 2
    if n > 1:
        fac[n] = fac.get(n, 0) + 1
    return fac


def gen_divisors_from_factorization(items, idx=0, cur=1, out=None):
    if out is None:
        out = []
    if idx == len(items):
        out.append(cur)
        return out
    p, e = items[idx]
    val = 1
    for _ in range(e + 1):
        gen_divisors_from_factorization(items, idx + 1, cur * val, out)
        val *= p
    return out


def phi_from_m_factorization(n: int, m_primes):
    res = n
    t = n
    for p in m_primes:
        if t % p == 0:
            res -= res // p
            while t % p == 0:
                t //= p
        if t == 1:
            break
    return res


def factorize_with_known_primes(n: int, primes):
    fac = {}
    t = n
    for p in primes:
        if p * p > t:
            break
        if t % p == 0:
            c = 0
            while t % p == 0:
                t //= p
                c += 1
            fac[p] = c
    if t > 1:
        fac[t] = fac.get(t, 0) + 1
    return fac


def multiplicative_order(x: int, n: int, phi_n: int, phi_factors):
    if n == 1:
        return 1
    ordv = phi_n
    for p in phi_factors:
        while ordv % p == 0 and pow(x, ordv // p, n) == 1:
            ordv //= p
    return ordv


def main():
    data = sys.stdin.readline().strip().split()
    if not data:
        return
    m, x = map(int, data)

    m_fac = factorize(m)
    m_primes = list(m_fac.keys())
    divisors = gen_divisors_from_factorization(list(m_fac.items()))

    ans = 0
    for n in divisors:
        phi_n = phi_from_m_factorization(n, m_primes)
        phi_fac = factorize_with_known_primes(phi_n, m_primes)
        # phi(n) may contain primes not dividing m, so factor remaining part fully if needed
        rem = 1
        for p, e in phi_fac.items():
            rem *= p ** e
        if rem != phi_n:
            extra = factorize(phi_n // rem)
            for p, e in extra.items():
                phi_fac[p] = phi_fac.get(p, 0) + e
        ord_n = multiplicative_order(x % n if n != 1 else 0, n, phi_n, phi_fac)
        ans += phi_n // ord_n

    print(ans)


if __name__ == "__main__":
    main()

