    data = sys.stdin.read().strip().split()
    if not data:
        return
    n = int(data[0])
    s = data[1].strip()
    m = len(s)

    if m == 1:
        # Avoiding s means all characters are the opposite bit.
        print((1 << n) - 1)
        return

    L = m - 1
    N = 1 << L
    pat = int(s, 2)
    maskL = N - 1

    A = [[0] * N for _ in range(N)]
    for x in range(N):
        for b in (0, 1):
            w = (x << 1) | b  # length-m window as bits
            if w == pat:
                continue
            y = w & maskL
            A[x][y] += 1

    An = mat_pow(A, n)
    avoid = sum(An[i][i] for i in range(N))
    total = 1 << n
    print(total - avoid)


