def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    n_str, k_str = data
    k = int(k_str)

    s = n_str
    m = len(s)

    # Option 1: make the result exactly "0" by keeping one zero digit.
    ans = m - 1 if '0' in s else 10**18

    # Option 2: keep a subsequence ending with at least k zeros.
    zeros_found = 0
    deletions = 0

    for i in range(m - 1, -1, -1):
        if s[i] == '0':
            zeros_found += 1
            if zeros_found == k:
                # Need at least one digit before these k trailing zeros,
                # otherwise the result would have leading zeros only and must be written as "0".
                if i > 0:
                    ans = min(ans, deletions)
                else:
                    ans = min(ans, deletions + 1)
                break
        else:
            if zeros_found < k:
                deletions += 1

    print(ans)


if __name__ == "__main__":
