import sys


def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    b1, q, l, m = map(int, data[:4])
    bad = set(map(int, data[4:4 + m]))

    if abs(b1) > l:
        print(0)
        return

    if q == 0:
        # Terms: b1, 0, 0, 0, ...
        if b1 == 0:
            print(0 if 0 in bad else 'inf')
            return
        # First term may be counted if not bad; then infinitely many zeros if 0 not bad
        if 0 not in bad:
            print('inf')
        else:
            print(0 if b1 in bad else 1)
        return

    if q == 1:
        print(0 if b1 in bad else 'inf')
        return

    if q == -1:
        print(0 if (b1 in bad and -b1 in bad) else 'inf')
        return

    ans = 0
    cur = b1
    while abs(cur) <= l:
        if cur not in bad:
            ans += 1
        cur *= q

    print(ans)


if __name__ == '__main__':
    solve()

